class TestEnvironmentalIsolation:
    """Behavior under different environmental conditions."""

    @pytest.mark.parametrize("env_modifier", [
        {"PYTHONPATH": ""},
        {"PYTHONPATH": "/nonexistent/path"},
        {"LANG": "C"},
        {"LC_ALL": "C"},
    ])
    def test_environment_variations(self, env_modifier):
        """Verify script works across different environment configurations."""
        env = os.environ.copy()
        env.update(env_modifier)
        result = run_script(env=env)
        assert result.returncode == 0, f"Failed with env {env_modifier}"
        assert result.stdout.strip() == EXPECTED_OUTPUT

    def test_no_environment(self):
        """Verify script works with minimal environment."""
        result = run_script(env={})
        assert result.returncode == 0, "Failed with empty environment"
        assert result.stdout.strip() == EXPECTED_OUTPUT

    def test_working_directory_independence(self, tmp_path):
        """Verify script works from different working directories."""
        result = subprocess.run(
            [sys.executable, str(SCRIPT_PATH)],
            capture_output=True,
            text=True,
            cwd=str(tmp_path)
        )
        assert result.returncode == 0, "Failed from different working directory"
        assert result.stdout.strip() == EXPECTED_OUTPUT


