class TestConcurrency:
    """Concurrent execution safety."""

    def test_parallel_execution(self):
        """Verify multiple concurrent executions produce correct output."""
        import concurrent.futures

        def execute():
            return run_script().stdout.strip()

        with concurrent.futures.ThreadPoolExecutor(max_workers=4) as executor:
            results = list(executor.map(lambda _: execute(), range(4)))

        assert all(r == EXPECTED_OUTPUT for r in results), (
            f"Concurrent execution failed: {results}"
        )


